CREATE COLUMN TABLE "TEST_AP"."OHED" ("edType" INTEGER CS_INT NOT NULL , "name" NVARCHAR(20) NOT NULL , "descriptio" NCLOB MEMORY THRESHOLD 1000, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("edType")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OHED_NAME_KEY" ON "TEST_AP"."OHED" ( "name" ASC )